    // Validate period_date
    if (input.period_date === undefined || input.period_date === null || input.period_date === '') {
      throw new Error('期間日付が不正です');
    }
  
    // Calculate divergence rate: ((actual - prediction) / prediction) * 100
    const divergenceRate = ((input.actual_value - input.prediction_value) / input.prediction_value) * 100;
  
    // Round to 2 decimal places
    const roundedDivergenceRate = Math.round(divergenceRate * 100) / 100;
  
    // Determine if improvement analysis is required (threshold: 10% or more deviation)
