/* AIVIC_FUNCTION_BUNDLE_START owner=filterAnomalousAndMissingData exports=filterAnomalousAndMissingData */
const __aivicBundle_11_filterAnomalousAndMissingData = (() => {
  async function filterAnomalousAndMissingData(
    malformedExpenseData: {
      user_id: string;
      expense_records: Array<{
        record_date: string;
        amount?: number;
        category: string;
      }>;
    }
  ): Promise<{
    error_log: {
      error_code: string;
      error_level: string;
      timestamp: string;
      message: string;
      affected_records: Array<number>;
      processing_halted: boolean;
    };
    processing_halted: boolean;
    processed_records?: Array<any>;
    valid_records: Array<any>;
    system_recoverable: boolean;
    user_notification: {
      message: string;
      severity: string;
    };
  }> {
    // Validate required input: user_id
    if (
      malformedExpenseData.user_id === undefined ||
      malformedExpenseData.user_id === null ||
      String(malformedExpenseData.user_id).trim() === ""
    ) {
      throw new Error("user_id is required");
    }
  
    const timestamp = new Date().toISOString();
    const affectedRecordIndices: number[] = [];
    const validRecords: Array<any> = [];
  
    // Validate each expense record
    for (let i = 0; i < malformedExpenseData.expense_records.length; i++) {
      const record = malformedExpenseData.expense_records[i];
      let isValid = true;
  
      // Check for missing amount field
      if (record.amount === undefined || record.amount === null) {
        affectedRecordIndices.push(i);
        isValid = false;
      }
  
      // Check for negative amount (anomalous)
      if (record.amount !== undefined && record.amount < 0) {
        if (!affectedRecordIndices.includes(i)) {
          affectedRecordIndices.push(i);
        }
        isValid = false;
      }
  
      // Check for invalid date format (basic ISO 8601 validation)
      if (record.record_date) {
        const dateRegex = /^\d{4}-\d{2}-\d{2}$/;
        if (!dateRegex.test(record.record_date)) {
          if (!affectedRecordIndices.includes(i)) {
            affectedRecordIndices.push(i);
          }
          isValid = false;
        }
      }
  
      // Check for unrealistic amounts (anomalous: extremely high values)
      if (record.amount !== undefined && record.amount > 1000000) {
        if (!affectedRecordIndices.includes(i)) {
          affectedRecordIndices.push(i);
        }
        isValid = false;
      }
  
      if (isValid) {
        validRecords.push(record);
      }
    }
  
    // Determine if validation failed
    const validationFailed = affectedRecordIndices.length > 0;
  
    const errorLog = {
      error_code: "DATA_VALIDATION_FAILED",
      error_level: "ERROR",
      timestamp: timestamp,
      message: "Expense record validation failed: missing required field(s)",
      affected_records: affectedRecordIndices,
      processing_halted: validationFailed,
    };
  
    const userNotification = {
      message: "食費データの検証に失敗しました",
      severity: "error",
    };
  
    return {
      error_log: errorLog,
      processing_halted: validationFailed,
      valid_records: validationFailed ? [] : validRecords,
      system_recoverable: true,
      user_notification: userNotification,
    };
  }
  return { filterAnomalousAndMissingData };
})();
export const filterAnomalousAndMissingData = __aivicBundle_11_filterAnomalousAndMissingData.filterAnomalousAndMissingData;
/* AIVIC_FUNCTION_BUNDLE_END owner=filterAnomalousAndMissingData */

