    const {
      verification_id,
      user_id,
      meal_list_id,
      use_fallback = false,
      fallback_mode,
      check_start_time,
      current_time,
    } = input;
  
    // Validate required inputs
    if (!String(user_id).trim()) {
      throw new Error('user_id is required');
    }
    if (!String(meal_list_id).trim()) {
      throw new Error('meal_list_id is required');
    }
  
    const sla_threshold_ms = 24 * 60 * 60 * 1000;
    const time_elapsed_ms = current_time.getTime() - check_start_time.getTime();
    const is_sla_exceeded = time_elapsed_ms > sla_threshold_ms;
  
    let status = 'completed';
    let processing_mode = 'normal';
    let fallback_executed = false;
    let system_log = '';
