const __aivicBundle_15_detectSlaDelayAndExecuteFallback = (() => {
  function detectSlaDelayAndExecuteFallback(input: {
    processStartTime: Date;
    currentCheckTime: Date;
    slaThresholdMs: number;
    logger?: { logs: string[] };
    fallbackExecutor?: (params: { delayMs: number; triggeredAt: Date }) => void;
  }): { isDelayed: boolean; elapsedMs: number; message: string } {
    const elapsedMs = input.currentCheckTime.getTime() - input.processStartTime.getTime();
    const isDelayed = elapsedMs >= input.slaThresholdMs;
  
    const message = isDelayed ? "遅延あり" : "遅延なし";
  
    if (isDelayed && input.fallbackExecutor) {
      const delayMs = elapsedMs - input.slaThresholdMs;
      input.fallbackExecutor({
        delayMs,
        triggeredAt: input.currentCheckTime,
      });
  
      if (input.logger) {
        input.logger.logs.push(
          `[${input.currentCheckTime.toISOString()}] SLA遅延検出: 経過時間=${elapsedMs}ms, 閾値=${input.slaThresholdMs}ms, 超過=${delayMs}ms`
        );
        input.logger.logs.push(
          `[${input.currentCheckTime.toISOString()}] 代替処理を実行しました`
        );
      }
    }
  
    return {
      isDelayed,
      elapsedMs,
      message,
    };
  }
  return { detectSlaDelayAndExecuteFallback };
})();
