const __aivicBundle_20_detectAccuracyDeclineAndExtractMainFactors = (() => {
  function detectAccuracyDeclineAndExtractMainFactors(input: {
    previous_month_accuracy: number;
    current_month_accuracy: number;
  }): AccuracyDeclineCheckResult {
    const declinePercentage = input.previous_month_accuracy - input.current_month_accuracy;
    const accuracyDeclined = declinePercentage >= 10;
  
    if (!accuracyDeclined) {
      return {
        accuracy_declined: false,
        main_factors_extracted: false,
        main_factors: [],
        extraction_log_entry_created: false,
        system_error_occurred: false,
      };
    }
  
    const mainFactors = extractMainFactorsInternal(
      input.previous_month_accuracy,
      input.current_month_accuracy,
      declinePercentage
    );
  
    const extractionLogCreated = createExtractionLogEntry(
      input.previous_month_accuracy,
      input.current_month_accuracy,
      mainFactors
    );
  
    return {
      accuracy_declined: true,
      main_factors_extracted: true,
      main_factors: mainFactors,
      extraction_log_entry_created: extractionLogCreated,
      system_error_occurred: false,
    };
  }
  
  function extractMainFactorsInternal(
    previousAccuracy: number,
    currentAccuracy: number,
    declinePercentage: number
  ): Array<any> {
    const factors: Array<any> = [];
  
    if (declinePercentage >= 10 && declinePercentage < 20) {
      factors.push({
        factor_type: "moderate_decline",
        factor_description: "Moderate accuracy decline detected",
        impact_score: declinePercentage,
        priority: 2,
      });
    } else if (declinePercentage >= 20) {
      factors.push({
        factor_type: "severe_decline",
        factor_description: "Severe accuracy decline detected",
        impact_score: declinePercentage,
        priority: 1,
      });
    }
  
    return factors;
  }
  
  function createExtractionLogEntry(
    previousAccuracy: number,
    currentAccuracy: number,
    mainFactors: Array<any>
  ): boolean {
    if (mainFactors.length === 0) {
      return false;
    }
  
    return true;
  }
  return { detectAccuracyDeclineAndExtractMainFactors };
})();
